 * Helpers for reading and interpreting Codex JSONL transcript files.
 */

import * as fs from 'fs';
import type { ContentBlock, RolloutLine } from './types';

const NANOSECONDS_PER_MS = 1_000_000;

/**
 * Reads a JSONL transcript file from disk and returns an array of parsed
 * RolloutLine records (one per non-empty line).
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const records: RolloutLine[] = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.length === 0) {
      continue;
    }
    try {
      records.push(JSON.parse(trimmed) as RolloutLine);
    } catch {
      // Skip malformed lines rather than failing the entire read.
    }
  }

  return records;
}

/**
 * Parses an ISO 8601 timestamp string into a nanosecond integer.
 * Returns null for null, undefined, or empty string inputs (or unparseable values).
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input === null || input === undefined || input === '') {
    return null;
  }

  const ms = Date.parse(input);
  if (Number.isNaN(ms)) {
    return null;
  }

  return ms * NANOSECONDS_PER_MS;
}

/**
 * Extracts plain text from a content block array (joining entries with '\n'),
 * returns a string argument unchanged, and returns '' for undefined.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }
  if (typeof content === 'string') {
    return content;
  }
  if (Array.isArray(content)) {
    return content
      .filter((block) => block != null && typeof block.text === 'string')
      .map((block) => block.text)
      .join('\n');
  }
  return '';
}

/**
 * Coerce an arbitrary function_call_output `output` value into a string.
 */
export function outputToString(output: unknown): string {
  if (output === null || output === undefined) {
    return '';
  }
  if (typeof output === 'string') {
    return output;
  }
  if (Array.isArray(output)) {
    return extractTextFromContent(output as ContentBlock[]);
  }
  if (typeof output === 'object') {
    const obj = output as Record<string, unknown>;
    if (typeof obj.output === 'string') {
      return obj.output;
    }
    if (typeof obj.content === 'string') {
      return obj.content;
    }
    if (Array.isArray(obj.content)) {
      return extractTextFromContent(obj.content as ContentBlock[]);
    }
    return JSON.stringify(output);
  }
  return String(output);
}

/**
 * Returns an object with a `text` property containing the last user message
 * text found in the transcript, or null if none exists.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.payload?.role === 'user') {
      return { text: extractTextFromContent(record.payload.content) };
    }
  }
  return null;
}

/**
 * Returns the subset of records belonging to the most recent turn — from the
 * task_started event_msg through the task_complete event_msg, inclusive.
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  let startIdx = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'task_started') {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) {
    return [];
  }

  let endIdx = records.length - 1;
  for (let i = records.length - 1; i >= startIdx; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'task_complete') {
      endIdx = i;
      break;
    }
  }

  return records.slice(startIdx, endIdx + 1);
}

/**
 * Finds the token_count event in the transcript and returns an object with
 * input_tokens, output_tokens, and total_tokens. Returns null if not found.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload?.type === 'token_count') {
      const info = (record.payload.info ?? record.payload) as Record<string, unknown>;
      const usage = ((info.total_token_usage as Record<string, unknown>) ?? info) as Record<
        string,
        unknown
      >;

      const inputTokens = Number(usage.input_tokens ?? 0);
      const outputTokens = Number(usage.output_tokens ?? 0);
      const totalTokens =
        usage.total_tokens != null ? Number(usage.total_tokens) : inputTokens + outputTokens;

      return {
        input_tokens: inputTokens,
        output_tokens: outputTokens,
        total_tokens: totalTokens,
      };
    }
  }
  return null;
}

/**
 * Returns the model name from the session_meta record. Returns 'unknown' when
 * no model is present in the session metadata.
 */
export function getModel(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      const payload = record.payload as Record<string, unknown>;
      const info = (payload.info as Record<string, unknown>) ?? {};
      const model = payload.model ?? info.model;
      if (typeof model === 'string' && model.length > 0) {
        return model;
      }
      return 'unknown';
    }
  }
  return 'unknown';
}

/**
 * Returns the session ID from the session_meta record in the transcript.
 */
export function getSessionId(records: RolloutLine[]): string {
  for (const record of records) {
    if (record.type === 'session_meta') {
      const payload = record.payload as Record<string, unknown>;
      const id = payload.id ?? payload.session_id ?? payload.sessionId;
      return id != null ? String(id) : '';
    }
  }
  return '';
}

/**
 * Builds a map from call_id strings to tool output strings by scanning
 * function_call_output records. Returns an empty object if none are present.
 */
export function buildToolResultMap(records: RolloutLine[]): Record<string, string> {
  const map: Record<string, string> = {};

  for (const record of records) {
    if (record.payload?.type === 'function_call_output') {
      const callId = record.payload.call_id;
      if (callId != null) {
        map[callId] = outputToString(record.payload.output);
      }
    }
  }

  return map;
}
