let initialized = false;

/**
 * Best-effort initialization of the MLflow SDK from environment variables.
 * Never throws and never blocks span creation — the SDK resolves the tracking
 * URI / experiment ID from the environment when available.
 */
function ensureInitialized(): void {
  if (initialized) {
    return;
  }
  initialized = true;
  try {
    if (typeof init === 'function') {
      init({
        trackingUri: process.env.MLFLOW_TRACKING_URI,
        experimentId: process.env.MLFLOW_EXPERIMENT_ID,
      });
    }
  } catch {
    // Ignore initialization failures; tracing simply becomes a no-op.
  }
}

/**
 * Attach the session/user trace metadata to the trace owning `traceId`.
 */
function setTraceMetadata(traceId: string, sessionId: string): void {
  try {
    const traceManager = InMemoryTraceManager.getInstance();
    const trace = traceManager.getTrace(traceId);
    if (trace) {
      trace.info.traceMetadata = {
        ...trace.info.traceMetadata,
        [TraceMetadataKey.TRACE_SESSION]: sessionId,
        [TraceMetadataKey.TRACE_USER]: process.env.USER || 'unknown',
      };
    }
  } catch {
    // Metadata is best-effort; never fail the trace over it.
  }
}

/**
 * Processes an agent-turn-complete notification payload, creating MLflow spans
 * for the completed turn.
 */
export async function processNotify(payload: NotifyPayload): Promise<void> {
  const inputMessages = payload['input-messages'] ?? [];

  // Nothing to trace: create no spans and do not flush.
  if (inputMessages.length === 0) {
    return;
  }

  ensureInitialized();

  const lastInput = inputMessages[inputMessages.length - 1];
  const lastAssistant = payload['last-assistant-message'];

  // Root AGENT span for the whole conversation turn.
  const rootSpan = startSpan({
    name: 'codex_conversation',
    spanType: SpanType.AGENT,
    inputs: lastInput,
  });

  // Single LLM child span summarizing the exchange.
  const llmSpan = startSpan({
    name: 'llm_call',
    parent: rootSpan,
    spanType: SpanType.LLM,
    inputs: {
      model: 'unknown',
      messages: [{ role: 'user', content: lastInput }],
    },
  });
  llmSpan.setOutputs({
    choices: [{ message: { role: 'assistant', content: lastAssistant } }],
  });
  llmSpan.end();

  rootSpan.setOutputs(lastAssistant);
  setTraceMetadata(rootSpan.traceId, payload['thread-id']);
